<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input';
type Event = { id: string; actor: string; action: string; resource_type: string; resource_id: string; ip_address: string | null; correlation_id: string | null; before_data: unknown; after_data: unknown; created_at: string };
const props = defineProps<{ events: { data: Event[] }; filters: { search: string } }>(); const search = ref(props.filters.search); const applySearch = () => router.get('/audit', { search: search.value }, { preserveState: true, replace: true });
</script>
<template><Head title="Auditoría" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Auditoría</h1><p class="text-sm text-muted-foreground">Accesos y cambios sensibles con actor, origen y correlación.</p></header><form class="flex max-w-xl gap-2" @submit.prevent="applySearch"><Input v-model="search" placeholder="Acción, recurso o identificador" /><Button type="submit" variant="outline">Buscar</Button></form><section class="space-y-2"><details v-for="event in events.data" :key="event.id" class="rounded-lg border bg-card p-4"><summary class="cursor-pointer list-none"><div class="flex flex-col justify-between gap-1 sm:flex-row"><div><span class="font-medium">{{ event.action }}</span><span class="ml-2 text-sm text-muted-foreground">{{ event.resource_type }} #{{ event.resource_id }}</span></div><span class="text-xs text-muted-foreground">{{ event.created_at }}</span></div><p class="mt-1 text-xs text-muted-foreground">{{ event.actor }} · {{ event.ip_address || 'sin IP' }} · {{ event.correlation_id }}</p></summary><div class="mt-4 grid gap-3 border-t pt-3 md:grid-cols-2"><div><h3 class="mb-1 text-xs font-medium">Antes</h3><pre class="overflow-auto rounded bg-muted p-3 text-xs">{{ JSON.stringify(event.before_data, null, 2) }}</pre></div><div><h3 class="mb-1 text-xs font-medium">Después</h3><pre class="overflow-auto rounded bg-muted p-3 text-xs">{{ JSON.stringify(event.after_data, null, 2) }}</pre></div></div></details><p v-if="events.data.length === 0" class="rounded-xl border p-10 text-center text-sm text-muted-foreground">No hay eventos para mostrar.</p></section></main></template>
